use super::*;
use crate::model::DeepSeekModel;
use aster_power::inference::InferenceLimits;
use sha2::{Digest, Sha256};

fn architecture() -> TextArchitecture {
    let config = DeepSeekModel::V41Flash1017Official
        .verify_config(include_bytes!("../../../fixtures/official-config.json"))
        .unwrap();
    TextArchitecture::from_checkpoint(&config).unwrap()
}

#[test]
fn every_base_layer_matches_independently_observed_official_header_digest() {
    // The fixture is the read-only audit of all official shard headers, not
    // generated by LayerWeightSchema. Canonical records have LF separators.
    let observed: serde_json::Value = serde_json::from_str(include_str!(
        "../../../fixtures/official-text-layer-descriptors.json"
    ))
    .unwrap();
    assert_eq!(
        observed["checkpoint_revision"],
        crate::model::OFFICIAL_REVISION
    );
    assert_eq!(
        observed["index_sha256"],
        crate::model::OFFICIAL_INDEX_SHA256
    );
    let architecture = architecture();
    let schema = TextWeightSchema::new(&architecture);
    assert_eq!(schema.layers().len(), 40);
    let mut count = 0;
    for (layer, frozen) in schema
        .layers()
        .iter()
        .zip(observed["layers"].as_array().unwrap())
    {
        let tensors = layer.tensors();
        let mut canonical = String::new();
        for tensor in &tensors {
            use std::fmt::Write;
            let shape = tensor
                .shape()
                .iter()
                .map(usize::to_string)
                .collect::<Vec<_>>()
                .join(",");
            writeln!(
                canonical,
                "{}|{}|{}|{}",
                tensor.name(),
                tensor.dtype().to_ascii_uppercase(),
                shape,
                tensor.bytes()
            )
            .unwrap();
        }
        assert_eq!(layer.layer() as u64, frozen["layer"].as_u64().unwrap());
        assert_eq!(
            tensors.len() as u64,
            frozen["tensor_count"].as_u64().unwrap()
        );
        assert_eq!(
            tensors.iter().map(ParameterBinding::bytes).sum::<u64>(),
            frozen["tensor_bytes"].as_u64().unwrap()
        );
        assert_eq!(
            format!("{:x}", Sha256::digest(canonical.as_bytes())),
            frozen["sorted_descriptor_sha256"].as_str().unwrap(),
            "layer {}",
            layer.layer()
        );
        count += tensors.len();
    }
    assert_eq!(count, 93415);
    assert_eq!(schema.embedding.logical_shape(), [129280, 5120]);
    assert_eq!(schema.head.weight_name(), "head.weight");
    assert_eq!(schema.norm.shape(), &[5120]);
}

#[test]
fn shared_state_consumers_bind_only_their_actual_owned_parameters() {
    let architecture = architecture();
    let schema = TextWeightSchema::new(&architecture);
    for layer in schema.layers() {
        let id = layer.layer();
        assert_eq!(layer.compressor.is_some(), [2, 8, 14, 20].contains(&id));
        assert_eq!(layer.index_key.is_some(), [2, 8, 14, 20].contains(&id));
        assert_eq!(
            layer.index_query.is_some(),
            [2, 8, 14, 20, 24, 28, 32, 36].contains(&id)
        );
        assert_eq!(layer.engram.is_some(), [1, 14].contains(&id));
        if let Some(compressor) = &layer.compressor {
            assert_eq!(compressor.gate.is_some(), id != 20);
        }
        assert_eq!(layer.ffn.routed.len(), 384);
        assert_eq!(layer.ffn.routed[383].down.logical_shape(), [5120, 2304]);
        assert_eq!(
            layer.ffn.routed[0].gate.layout(),
            MatrixLayout::Mxfp4Block32
        );
        assert_eq!(layer.ffn.shared.gate.layout(), MatrixLayout::Fp8Block32);
    }
    assert_eq!(
        schema.layers()[1].engram.as_ref().unwrap().table.layout(),
        MatrixLayout::Fp8Row32
    );
}

#[test]
fn small_parameter_upload_preserves_exported_fp32_bf16_bits_and_refuses_nonfinite() {
    let device = CudaLayerDevice::cpu_for_tests(InferenceLimits::default());
    let cancellation = CancellationToken::new();
    let floats = [1.000_000_1_f32, -0., f32::from_bits(1), -12.5];
    let raw = floats
        .iter()
        .flat_map(|v| v.to_le_bytes())
        .collect::<Vec<_>>();
    let (_dir, weights) = super::super::tests::fixture(&[("layer.fn", "F32", vec![2, 2], raw)], 16);
    let binding = ParameterBinding::new("layer.fn", "f32", &[2, 2]);
    let loaded = binding.load(&weights, &device, &cancellation).unwrap();
    let actual = loaded.flatten_all().unwrap().to_vec1::<f32>().unwrap();
    assert_eq!(
        actual.iter().map(|x| x.to_bits()).collect::<Vec<_>>(),
        floats.map(f32::to_bits)
    );

    let raw = [0x8000_u16, 0x0001, 0x3f80, 0xbf80]
        .into_iter()
        .flat_map(u16::to_le_bytes)
        .collect::<Vec<_>>();
    let (_dir, weights) = super::super::tests::fixture(&[("layer.norm", "BF16", vec![4], raw)], 8);
    let binding = ParameterBinding::new("layer.norm", "bf16", &[4]);
    let actual = binding
        .load(&weights, &device, &cancellation)
        .unwrap()
        .to_dtype(DType::F32)
        .unwrap()
        .to_vec1::<f32>()
        .unwrap();
    assert_eq!(
        actual.iter().map(|x| x.to_bits()).collect::<Vec<_>>(),
        [0x80000000, 0x00010000, 0x3f800000, 0xbf800000]
    );

    for v in [f32::NAN, f32::INFINITY, f32::NEG_INFINITY] {
        let (_dir, weights) =
            super::super::tests::fixture(&[("bad", "F32", vec![1], v.to_le_bytes().to_vec())], 4);
        assert!(ParameterBinding::new("bad", "f32", &[1])
            .load(&weights, &device, &cancellation)
            .is_err());
    }
}

#[test]
fn parameter_upload_refuses_shape_dtype_budget_quantized_and_cancellation() {
    let (_dir, weights) = super::super::tests::fixture(&[("p", "F32", vec![2], vec![0; 8])], 8);
    let device = CudaLayerDevice::cpu_for_tests(InferenceLimits::default());
    let cancellation = CancellationToken::new();
    for binding in [
        ParameterBinding::new("missing", "f32", &[2]),
        ParameterBinding::new("p", "bf16", &[2]),
        ParameterBinding::new("p", "f32", &[1, 2]),
        ParameterBinding::new("p", "f8_e4m3", &[2]),
    ] {
        assert!(binding.load(&weights, &device, &cancellation).is_err());
    }
    let binding = ParameterBinding::new("p", "f32", &[2]);
    let (_small_dir, small) = super::super::tests::fixture(&[("p", "F32", vec![2], vec![0; 8])], 7);
    assert!(binding.load(&small, &device, &cancellation).is_err());
    for limits in [
        InferenceLimits {
            max_resident_weight_bytes: 7,
            ..InferenceLimits::default()
        },
        InferenceLimits {
            max_state_bytes: 127,
            ..InferenceLimits::default()
        },
    ] {
        assert!(binding
            .load(
                &weights,
                &CudaLayerDevice::cpu_for_tests(limits),
                &cancellation
            )
            .is_err());
    }
    cancellation.cancel();
    assert!(binding.load(&weights, &device, &cancellation).is_err());
}

#[test]
fn parameter_namespace_refuses_unknown_missing_duplicate_and_wrong_shape() {
    let (_dir, weights) = super::super::tests::fixture(
        &[
            ("layers.2.p", "F32", vec![2], vec![0; 8]),
            ("layers.20.unrelated", "F32", vec![1], vec![0; 4]),
        ],
        8,
    );
    let cancellation = CancellationToken::new();
    let correct = ParameterBinding::new("layers.2.p", "f32", &[2]);
    validate_namespace(
        &weights,
        "layers.2.",
        std::slice::from_ref(&correct),
        &cancellation,
    )
    .unwrap();
    for tensors in [
        vec![],
        vec![correct.clone(), correct.clone()],
        vec![ParameterBinding::new("layers.2.missing", "f32", &[2])],
        vec![ParameterBinding::new("layers.2.p", "f32", &[1, 2])],
    ] {
        assert!(validate_namespace(&weights, "layers.2.", &tensors, &cancellation).is_err());
    }
    let (_extra_dir, extra) = super::super::tests::fixture(
        &[
            ("layers.2.p", "F32", vec![2], vec![0; 8]),
            ("layers.2.unexpected", "F32", vec![1], vec![0; 4]),
        ],
        8,
    );
    assert!(validate_namespace(&extra, "layers.2.", &[correct], &cancellation).is_err());
}

#[test]
fn explicit_matrix_binding_keeps_packed_container_and_its_exact_scale_layout() {
    let (_dir, weights) = super::super::tests::fixture(
        &[
            ("expert.weight", "I8", vec![1, 16], vec![0xab; 16]),
            ("expert.scale", "F8_E8M0", vec![1, 1], vec![127]),
        ],
        17,
    );
    let binding = MatrixBinding::new("expert", MatrixLayout::Mxfp4Block32, [1, 32]);
    let bound = binding.bind(&weights).unwrap();
    let raw = bound.read_rows(0, 1, &CancellationToken::new()).unwrap();
    assert_eq!(raw.weight.bytes(), &[0xab; 16]);
    assert_eq!(raw.scale.unwrap().bytes(), &[127]);
    assert!(
        MatrixBinding::new("expert", MatrixLayout::Fp8Row32, [1, 16])
            .bind(&weights)
            .is_err()
    );
    assert!(
        MatrixBinding::new("expert", MatrixLayout::Mxfp4Block32, [1, 64])
            .bind(&weights)
            .is_err()
    );
}
